S=/private/tmp/claude-501/-Users-[REDACTED:user]-leveraged-etf-risk-analytics/c82fe879-2a08-4e8f-a4c7-740b70b55e9a/scratchpad/caching-dry/dry-2; cd ~/leveraged-etf-risk-analytics && uv run python -I -c "
import json, pathlib, sys, collections
no_phase, fill_states, missing_where = collections.Counter(), collections.Counter(), collections.Counter()
for p in sorted(pathlib.Path(sys.argv[1]).rglob('plans.json')):
    config = p.relative_to(sys.argv[1]).parts[0]
    doc = json.loads(p.read_text())
    no_phase[(config, sum(1 for e in doc['executions'] if e['phase'] == ''))] += 1
    for e in doc['executions']:
        imts = [s for s in e['scans'] if s['node'] == 'InMemoryTableScan']
        fill = e['description'].startswith('cache fill: ')
        for s in imts:
            if fill:
                fill_states['missing' if s['rows'] is None else 'zero' if s['rows'] == 0 else 'positive'] += 1
        for s in e['scans']:
            if s['rows'] is None:
                missing_where[(s['node'], 'execution reads cached data' if imts else 'no cached read')] += 1
print('executions without a phase, per run:', dict(no_phase))
print('fill reads by row metric:', dict(fill_states))
print('scans with a missing row metric:', dict(missing_where))
" $S

